CREATE TABLE cover_consideration_events (event_id TEXT PRIMARY KEY NOT NULL CHECK(event_id GLOB 'cover_consideration_event_[0-9a-f]*' AND length(event_id)=90), consideration_id TEXT NOT NULL REFERENCES cover_considerations(consideration_id), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), kind TEXT NOT NULL CHECK(kind IN ('automatic_prepared','owner_retry_prepared','superseded','selected','kept_incumbent','no_action','stale')), decision_id TEXT, occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096));
