CREATE TABLE field_effect_suspensions (scope TEXT NOT NULL CHECK(scope IN ('connection','destination')), connection_name TEXT NOT NULL CHECK(length(connection_name) BETWEEN 1 AND 128), destination TEXT NOT NULL CHECK(length(destination)<=64 AND ((scope='connection' AND destination='') OR (scope='destination' AND length(destination)>=1))), reason TEXT NOT NULL CHECK(reason IN ('connection_unavailable','insufficient_permission','field_unavailable','unexpected_effect_behavior')), updated_at INTEGER NOT NULL CHECK(updated_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 4096), PRIMARY KEY(scope,connection_name,destination));
