CREATE TABLE human_decision_events (event_id TEXT PRIMARY KEY NOT NULL CHECK(event_id GLOB 'human_decision_event_[0-9a-f]*' AND length(event_id)=85), decision_id TEXT NOT NULL UNIQUE REFERENCES human_decisions(decision_id), review_case_id TEXT NOT NULL REFERENCES review_cases(review_case_id), destination TEXT NOT NULL CHECK(length(destination) BETWEEN 1 AND 64), actor TEXT NOT NULL CHECK(actor='owner'), kind TEXT NOT NULL CHECK(kind='human_decision_recorded'), occurred_at INTEGER NOT NULL CHECK(occurred_at>=0), document TEXT NOT NULL CHECK(typeof(document)='text' AND length(CAST(document AS BLOB)) BETWEEN 2 AND 65536));
