eded','missing_required_input','malformed_retained_data','internal_failure','unknown')), failure_root TEXT CHECK(failure_root IS NULL OR (typeof(failure_root)='text' AND length(CAST(failure_root AS BLOB)) BETWEEN 1 AND 64 AND ((failure_code='authentication' AND failure_root NOT GLOB '*[^a-z0-9_-]*' AND substr(failure_root,1,1) GLOB '[a-z]') OR (failure_code IN ('unsupported_media','unreadable_media','parser_refused','multi_file_budget_exceeded') AND (failure_root GLOB 'track_[1-9]' OR failure_root GLOB 'track_[1-9][0-9]' OR failure_root GLOB 'track_[1-9][0-9][0-9]'))))), presentation_recovery_cycle_id TEXT CHECK(presentation_recovery_cycle_id IS NULL OR (presentation_recovery_cycle_id GLOB 'preparation_cycle_[0-9a-f]*' AND length(presentation_recovery_cycle_id)=82)), presentation_recovery_stage TEXT CHECK(presentation_recovery_stage IS NULL OR presentation_recovery_stage IN ('extraction','provider','proposal','admission','projection')), presentation_recovery_outcome TEXT CHECK(presentation_recovery_outcome IS NULL OR presentation_recovery_outcome IN ('ready','failed')), updated_at INTEGER NOT NULL CHECK(updated_at>=0), CHECK((presentation_recovery_cycle_id IS NULL AND presentation_recovery_stage IS NULL AND presentation_recovery_outcome IS NULL) OR (presentation_recovery_cycle_id IS NOT NULL AND presentation_recovery_stage IS NOT NULL)), CHECK((state='complete')=(outcome IS NOT NULL)), CHECK(outcome IS NULL OR (outcome='case' AND review_case_id IS NOT NULL) OR (outcome='no_case' AND proposal_set_id IS NOT NULL AND review_case_id IS NULL) OR (outcome='evidence_only' AND report_id IS NOT NULL AND proposal_set_id IS NULL AND review_case_id IS NULL)), UNIQUE(scan_id,item_id));
